pid_t target_thread = 0; // Current thread
int rt_policy = SCHED_FIFO;

// Set required priority (e.g., 50)
struct sched_param params;
params.sched_priority = 50;

// Apply new scheduling policy and parameters
int status = sched_setscheduler(
    target_thread,
    rt_policy,
    &params
);

// Example for standard policy (SCHED_OTHER requires priority 0)
struct sched_param other_params = {
    .sched_priority = 0
};

sched_setscheduler(0, SCHED_OTHER, &other_params);
